<template><view class="page"><view class="wrap"><MobileHeader title="通知" back-icon-name="chevron-left" action-text="刷新" @action="load(true)"/><view class="filters"><view :class="{active:!unread}" @tap="filter(false)">全部</view><view :class="{active:unread}" @tap="filter(true)">未读</view></view><view v-for="notice in notices" :key="notice.id" class="card"><view class="row"><text>{{notice.templateNickname||'系统通知'}}</text><text class="badge">{{notice.readStatus?'已读':'未读'}}</text></view><view class="notice-content">{{notice.templateContent}}</view><view class="row"><text class="muted">{{formatDate(notice.createTime)}}</text><text v-if="!notice.readStatus" class="badge" role="button" @tap="read(notice.id)">标记已读</text></view></view><view v-if="!notices.length&&!busy" class="empty">暂无通知</view><view v-if="notices.length<total" class="empty" @tap="load(false)">{{busy?'加载中…':'加载更多'}}</view><text class="error">{{error}}</text></view></view></template><script setup lang="ts">import {ref} from 'vue';import {onShow,onReachBottom} from '@dcloudio/uni-app';import MobileHeader from '@/components/MobileHeader.vue';import {client,requireSession} from '@/platform';const notices=ref<any[]>([]),page=ref(1),total=ref(0),busy=ref(false),unread=ref(false),error=ref('');function formatDate(v:number){return v?new Date(v).toLocaleString():'';}async function load(reset=false){if(!requireSession()||busy.value)return;busy.value=true;error.value='';const next=reset?1:page.value;try{const r=await client.request('GET',`/admin-api/system/notify-message/my-page?pageNo=${next}&pageSize=20${unread.value?'&readStatus=false':''}`);notices.value=reset?r.list:[...notices.value,...r.list];total.value=r.total;page.value=next+1;}catch{error.value='通知加载失败，请重试';}finally{busy.value=false;}}async function read(id:number){try{await client.markRead(id);await load(true);}catch{error.value='标记已读失败，请重试';}}function filter(value:boolean){unread.value=value;void load(true);}onShow(()=>load(true));onReachBottom(()=>{if(notices.value.length<total.value)void load(false);});</script><style scoped lang="scss">.page{min-height:100vh;background:#f7f8fc;padding-bottom:calc(110px + env(safe-area-inset-bottom))}.wrap{max-width:500px;margin:auto;padding:0 15px}.section-title{font-size:17px;font-weight:600}.card{background:#fff;border-radius:18px;padding:18px;margin-top:14px;box-shadow:0 6px 16px rgba(20,31,51,.06)}.row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0;border-bottom:1px solid #eef1f6}.row:last-child{border:0}.muted{color:#8791a4;font-size:12px}.primary{margin-top:20px;background:#294fdb;color:white;border-radius:12px;font-size:14px}.field{padding:15px 0;border-bottom:1px solid #eef1f6}.field text{display:block;font-size:13px;color:#636e82;margin-bottom:10px}.field input{font-size:14px}.empty{padding:36px 0;text-align:center;color:#8791a4;font-size:14px}.badge{color:#294fdb;font-size:12px}.error{color:#d44545;font-size:13px;margin-top:12px}</style><style scoped>.filters{display:flex;gap:24px;padding:16px 4px;color:#8791a4}.filters .active{color:#294fdb;font-weight:600}.notice-content{padding:18px 0;font-size:14px;line-height:1.7}</style>
